function setupTransitionQA(){if(typeof location==='undefined'||new URLSearchParams(location.search).get('qa')!=='transition')return;const panel=document.createElement('div');panel.style.cssText='position:fixed;left:8px;bottom:12px;z-index:20;display:flex;gap:4px;flex-wrap:wrap;max-width:90vw;padding:6px;background:#121923e8;border:1px solid #a8ccdf;border-radius:8px;font-size:10px';panel.textContent=QA_SLOW?'TRANSITION TEST · 0.1×':'TRANSITION TEST';for(const [label,run]of [['CLEAR TARGETS',()=>{if(!started)return;for(const o of [...blocks.values()]){const origin=o.origin;removeCluster(o);awardOriginal(origin);}}],['MIRROR ON/OFF',()=>{const o=stageGroup.userData.mirror;o.visible=!o.visible;}],['COAT ON/OFF',()=>{const o=stageGroup.userData.coat;o.visible=!o.visible;}]]){const button=document.createElement('button');button.textContent=label;button.style.cssText='font-size:10px;padding:5px';button.onclick=run;panel.appendChild(button);}document.body.appendChild(panel);}
try{await RAPIER.init();setupScene();setupPhysics();bonusWorld=new BonusWorld({scene,controller:powers,radius:C.ballRadius,bounds:()=>({top:TOP,mid:MID,bottom:BOTTOM,half:tableHalf}),blocked:pickupBlocked,onSound:name=>audio.play(name),onNotice:message=>tell(message,1.5)});secondary=new SecondaryPowers({THREE,RAPIER,scene,world,colliders,radius:C.ballRadius,tableGroup:GROUP.table,structureGroup:GROUP.structure,onFinishSplit:id=>powers.finishSplit(id)});powerFX=new PowerFX({THREE,scene,radius:C.ballRadius});generateSection();await environmentReady;await warmGlassShaders();setupTransitionQA();setupBonusQA();setupBonusTestMenu();$('play').disabled=false;$('play').textContent='PLAY';let last=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.06);last=now;if(started&&!paused&&!bonusTestOpen){accumulator+=dt*(slow>0?.45:1);let n=0;while(accumulator>=C.step&&n++<C.maxSubsteps){step(C.step);accumulator-=C.step;}if(n>=C.maxSubsteps)accumulator=0;}render(dt);}requestAnimationFrame(frame);
 // Read-only diagnostics; Q opens the explicitly requested bonus test menu.
 window.crystalDiagnostics=()=>({version:'0.4.0',powers:powers.snapshotHUD(),pickups:bonusWorld.pickups.length,arena:arenaDefinition(section).name,state,score,section,targets:[...originals.values()].filter(o=>!o.rewarded).length,clusters:blocks.size,fragments:fragments.length,particles:dust.length,bodies:world.bodies.len(),drawCalls:renderer.info.render.calls,ball:{...ball.translation()},powerTime,echoes:secondary.echoes.map(e=>({position:{...e.b.translation()},held:e.isHeld,parked:e.transitionParked,staged:!!e.staged})),control:drag?.echo?'echo-aim':drag?.mode||null});
}catch(e){console.error(e);$('play').textContent='RELOAD TO RETRY';$('play').disabled=false;$('play').onclick=()=>location.reload();document.querySelector('#start p').textContent='The 3D engine could not start. Please use a WebGL-enabled browser.';}
